Section F16IA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT SY D V u0 len b nb R : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat)
            (cells0 : list (option deltX1)) (FRC : list cell).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HB : 0 <= b < 256.
  Hypothesis HNB : 0 <= nb < 16.
  Hypothesis HV : 0 <= V.
  Hypothesis HU0 : 0 <= u0.
  Hypothesis HLEN : 16 <= len /\ len mod 16 = 0.
  Hypothesis HVL : V + len <= Z.of_nat ncells.
  Hypothesis HDV : D + 2 * u0 = DT + 2 * V.
  Hypothesis HDT : ablk (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis HSY : ablk SY (SY + zlen js).
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis DSP : DT + 4 + 2 * Z.of_nat ncells <= SPA.
  Hypothesis SP47 : SPA + 312 <= 2^47.
  Hypothesis UDT : unpoisoned m0 (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis AWD : appW [(DT + 4, DT + 4 + 2 * Z.of_nat ncells); (SPA + 136, SPA + 296)].
  Hypothesis RDT : rng RNG (DT + 4) (2 * Z.of_nat ncells).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 2 * Z.of_nat ncells + DT mod 8)).
  Hypothesis LC0 : length cells0 = ncells.
  Hypothesis B32 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 32)) = [Z_to_bv 8 nb].
  Hypothesis B40 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 40)) = [Z_to_bv 8 b].
  Hypothesis B48 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 48)) = [Z_to_bv 8 nb].
  Hypothesis B56 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 56)) = [Z_to_bv 8 b].
  Hypothesis B24 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 24)) = [Z_to_bv 8 b].
  Hypothesis B16 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 16)) = [Z_to_bv 8 nb].
  Hypothesis B8 : le1 (Z_to_bv 64 (Z.land R 18446744073709551615 ≫ 8)) = [Z_to_bv 8 b].
  Hypothesis B0 : le1 (Z_to_bv 64 R) = [Z_to_bv 8 nb].
  Notation INV m1 cells := (x1fA_inv m0 m1 SPA DT SY js jt syms ncells cells).
  Notation C := (mkX1 nb b).
  Notation CH pc mm j x1 x5 x6 x7 x10 x12 x14 x15 x19 x27 x28 x29 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10
             (Z_to_bv 64 (Z.shiftr (DT + 4 + 2 * V + 32 * j) 3 + 2147450880)) x12 (Z_to_bv 64 (D + 11 + 32 * j)) x14 x15
             (Z_to_bv 64 R) (Z_to_bv 64 (D + 12 + 32 * j)) (Z_to_bv 64 (16 * j)) x19 (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (D + 28 + 32 * j)) (Z_to_bv 64 (D + 20 + 32 * j)) (Z_to_bv 64 (2 * u0)) (Z_to_bv 64 (D + 27 + 32 * j))
             (Z_to_bv 64 (D + 35 + 32 * j)) (Z_to_bv 64 (D + 4 + 32 * j)) x27 x28 x29
             (Z_to_bv 64 (D + 20 + 32 * j)) (Z_to_bv 64 (D + 19 + 32 * j)))
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma f16A_in : forall n j (x1 x5 x6 x7 x10 x12 x14 x15 x19 x28 x29 : word) m1,
    Z.of_nat n = len / 16 - j -> 0 <= j < len / 16 ->
    INV m1 (XM.updc cells0 (seq (Z.to_nat V) (Z.to_nat (16 * j))) C) -> rw_cells asegs m1 (SPA + 136) FRC ->
    (forall m2 (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y17 y18 y19 y21 y22 y24 y25 y26 y28 y29 y30 y31 : word),
       INV m2 (XM.updc cells0 (seq (Z.to_nat V) (Z.to_nat len)) C) -> rw_cells asegs m2 (SPA + 136) FRC ->
       evtF asegs RNG Q (MS (mkR y1 (Z_to_bv 64 SPA) gp tp y5 y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12 y13 y14 y15
                                 (Z_to_bv 64 R) y17 y18 y19 (Z_to_bv 64 2147450880) y21 y22 (Z_to_bv 64 (2 * u0)) y24 y25 y26
                                 (Z_to_bv 64 len) y28 y29 y30 y31)
                            F (Z_to_bv 64 0x80d90) fc None m2 (seg_rom asegs))) ->
