Section F16OA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT SY cnt sym0 len nb u0 w : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat)
            (j288 : list byte).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis HNB : 0 <= nb < 16.
  Hypothesis HU0 : 0 <= u0.
  Hypothesis HLEN : 16 <= len <= 2048 /\ len mod 16 = 0.
  Hypothesis HCNT : 0 <= cnt <= 256.
  Hypothesis HSYM : 0 <= sym0 <= 256.
  Hypothesis HDT : ablk (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis HSY : ablk SY (SY + zlen js).
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis DSP : DT + 4 + 2 * Z.of_nat ncells <= SPA.
  Hypothesis SYSP : SY + zlen js <= SPA.
  Hypothesis SP47 : SPA + 312 <= 2^47.
  Hypothesis UDT : unpoisoned m0 (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis ZSY : zshadow m0 SY (zlen js).
  Hypothesis AWD : appW [(DT + 4, DT + 4 + 2 * Z.of_nat ncells); (SPA + 136, SPA + 296)].
  Hypothesis RDT : rng RNG (DT + 4) (2 * Z.of_nat ncells).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 2 * Z.of_nat ncells + DT mod 8)).
  Hypothesis RSY : rng RNG SY (zlen js).
  Hypothesis RSYs : rng RNG (shad SY) (nshad (zlen js + SY mod 8)).
  Hypothesis RFR : rng RNG SPA 312.
  Notation INV m1 cells := (x1fA_inv m0 m1 SPA DT SY js jt syms ncells cells).
  Notation FR16 s := (x1fr16A w nb u0 len SY sym0 cnt s (DT + 2 * (len * s)) (DT + 4 + 2 * (u0 + len * s)) j288).

  Lemma f16A_out : forall f s cells m1 r
      (x1 x5 x6 x7 x10 x13 x14 x15 x16 x17 x18 x19 x21 x22 x24 x25 x26 x28 x29 x30 x31 : word),
    fill_syms f s cnt sym0 len nb syms cells (u0 + len * s) = Ok r ->
    Z.of_nat f = cnt - s + 1 -> 0 <= s < cnt -> INV m1 cells -> rw_cells asegs m1 (SPA + 136) (FR16 s) ->
    (forall m2 cells' (j144' j160' j192' j208' : list byte)
            (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y21 y22 y23 y24 y25 y26 y28 y29 y30 y31 : word),
       r = (cells', u0 + len * cnt) -> INV m2 cells' ->
       rw_cells asegs m2 (SPA + 136) (x1frA w u0 sym0 cnt SY j144' j160' j192' j208') ->
       evtF asegs RNG Q (x1nextA SP SPA len gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y21 y22 y23 y24
                           y25 y26 y28 y29 y30 y31)) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 (Z_to_bv 64 sym0)
                              (Z_to_bv 64 s) x13 x14 x15 x16 x17 x18 x19 (Z_to_bv 64 2147450880) x21 x22 (Z_to_bv 64 (2 * u0))
                              x24 x25 x26 (Z_to_bv 64 len) x28 x29 x30 x31)
